Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='fenceattheagent', at=datetime(2026, 9, 1, 0, 0, 0), actor='assistant', title='Containment lives in .claude/triage-settings.json, filled and probed by triage-fence.sh, never in .claude/settings.json', body='Containment is aimed at the AGENT, not this directory: it lives in `.claude/triage-settings.json`, a template `scripts/triage-fence.sh` fills with each guard\'s absolute path, failing closed (`\'<guard>\' || exit 2`), and probes before its spawner passes it (`hourly-triage.sh` with `--settings "$FENCE" --tools ToolSearch --strict-mcp-config`; a pass on new mail whose stream names no `mcp__suzatary__` call fails), never in `.claude/settings.json`, which every interactive session loads (while it held the deny list a plain session here could not write a file — measured, test-pinned). `--strict-mcp-config` keeps account-level MCP servers (an interactive session holds `mcp__claude_ai_Gmail__send_message`) off the agent.', rationale='Shipped in 0.10.0, 2026-09-01. Measured and test-pinned: while .claude/settings.json held the deny list, a plain session here could not write a file.', supersedes=()))